class _FrozenDict(dict):
    """A JSON-compatible dictionary that rejects mutation after construction."""

    def _immutable(self, *args, **kwargs):
        raise TypeError("receipt arguments are immutable")

    __delitem__ = _immutable
    __ior__ = _immutable
    __setitem__ = _immutable
    clear = _immutable
    pop = _immutable
    popitem = _immutable
    setdefault = _immutable
    update = _immutable


def _json_copy(value: Any) -> Any:
    """Validate and detach a JSON-compatible value."""

    try:
        encoded = json.dumps(
            value,
            allow_nan=False,
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
        )
        return json.loads(encoded)
    except (TypeError, ValueError) as error:
        raise ValueError("receipt payload must be JSON serializable") from error


def _freeze_json(value: Any) -> Any:
    if isinstance(value, dict):
        return _FrozenDict({key: _freeze_json(item) for key, item in value.items()})
    if isinstance(value, list):
        return tuple(_freeze_json(item) for item in value)
    return value


def _canonical_payload(value: Any) -> bytes:
    return json.dumps(
        value,
        allow_nan=False,
        ensure_ascii=True,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")


@dataclass(frozen=True)
class EffectReceipt:
    """Immutable, content-addressed evidence for one dispatched tool action."""

    tool_call_id: str
    tool: str
    arguments: dict[str, Any]
    exit_state: str
    result: str
    changed_artifacts: tuple[str, ...]

    def __post_init__(self) -> None:
        if not isinstance(self.tool_call_id, str) or not self.tool_call_id:
            raise ValueError("tool call ID must be a non-empty string")
        if not isinstance(self.tool, str) or not self.tool:
            raise ValueError("tool name must be a non-empty string")
        if self.exit_state not in {"ok", "error", "uncertain"}:
            raise ValueError("exit state must be ok, error, or uncertain")
        if not isinstance(self.result, str):
            raise ValueError("result must be a string")
        if not isinstance(self.arguments, dict):
            raise ValueError("receipt arguments must be a dictionary")
        if not isinstance(self.changed_artifacts, tuple) or not all(
            isinstance(path, str) and path for path in self.changed_artifacts
        ):
            raise ValueError("changed artifacts must be a tuple of paths")
        detached = _json_copy(self.arguments)
        object.__setattr__(self, "arguments", _freeze_json(detached))
        object.__setattr__(
            self, "changed_artifacts", tuple(sorted(set(self.changed_artifacts)))
        )

    @property
    def receipt_id(self) -> str:
        """Return the SHA-256 content address of the canonical receipt payload."""

        return hashlib.sha256(self._payload()).hexdigest()

    def _payload(self) -> bytes:
        return _canonical_payload(
            {
                "arguments": self.arguments,
                "changed_artifacts": self.changed_artifacts,
                "exit_state": self.exit_state,
                "result": self.result,
                "tool": self.tool,
                "tool_call_id": self.tool_call_id,
            }
        )

    def to_dict(self) -> dict[str, Any]:
        """Return a detached JSON-compatible durable representation."""

        return _json_copy(
            {
                "arguments": self.arguments,
                "changed_artifacts": self.changed_artifacts,
                "exit_state": self.exit_state,
                "receipt_id": self.receipt_id,
                "result": self.result,
                "tool": self.tool,
                "tool_call_id": self.tool_call_id,
            }
        )

    @classmethod
    def from_dict(cls, value: Any) -> "EffectReceipt":
        """Reconstruct a receipt and reject malformed or tampered payloads."""

        if not isinstance(value, dict):
            raise ValueError("receipt must be a JSON object")
        required = {
            "arguments",
            "changed_artifacts",
            "exit_state",
            "receipt_id",
            "result",
            "tool",
            "tool_call_id",
        }
        if set(value) != required:
            raise ValueError("invalid receipt fields")
        if not isinstance(value["changed_artifacts"], list):
            raise ValueError("changed artifacts must be a JSON array")
        receipt = cls(
            tool_call_id=value["tool_call_id"],
            tool=value["tool"],
            arguments=value["arguments"],
            exit_state=value["exit_state"],
            result=value["result"],
            changed_artifacts=tuple(value["changed_artifacts"]),
        )
        if not isinstance(value["receipt_id"], str) or (
            receipt.receipt_id != value["receipt_id"]
        ):
            raise ValueError("receipt digest does not match its payload")
        return receipt


class ReceiptStore:
    """Append-only receipt store with verification on write and reload."""

    def __init__(self, path: Path | None = None):
        self._path = Path(path).absolute() if path is not None else None
        self._receipts: dict[str, EffectReceipt] = {}
        self._by_tool_call: dict[str, str] = {}
        self._order: list[str] = []
        if self._path is not None:
            self._load()

    def _load(self) -> None:
        assert self._path is not None
        if not self._path.exists() and not self._path.is_symlink():
            return
        descriptor = self._open_file(os.O_RDONLY)
        with os.fdopen(descriptor, "r", encoding="utf-8") as handle:
            fcntl.flock(handle.fileno(), fcntl.LOCK_SH)
            for line_number, line in enumerate(handle, start=1):
                if not line.strip():
                    continue
                try:
                    receipt = EffectReceipt.from_dict(json.loads(line))
                except (json.JSONDecodeError, ValueError) as error:
                    raise ValueError(
                        f"invalid receipt at line {line_number}"
                    ) from error
                self._index(receipt)

    def _open_file(self, flags: int) -> int:
        assert self._path is not None
        try:
            descriptor = os.open(
                self._path,
                flags | getattr(os, "O_NOFOLLOW", 0),
                0o600,
            )
        except OSError as error:
            raise ValueError("receipt store path is unsafe") from error
        status = os.fstat(descriptor)
        if not stat.S_ISREG(status.st_mode) or status.st_nlink != 1:
            os.close(descriptor)
            raise ValueError("receipt store must be one regular file")
        return descriptor

    def _index(self, receipt: EffectReceipt) -> bool:
        receipt_id = receipt.receipt_id
        current_id = self._by_tool_call.get(receipt.tool_call_id)
        if current_id is not None and current_id != receipt_id:
            raise ValueError("tool call ID already belongs to another receipt")
        if receipt_id in self._receipts:
            return False
        self._receipts[receipt_id] = receipt
        self._by_tool_call[receipt.tool_call_id] = receipt_id
        self._order.append(receipt_id)
        return True

    def put(self, receipt: EffectReceipt) -> str:
        """Durably append one receipt, idempotently by content address."""

        if not isinstance(receipt, EffectReceipt):
            raise TypeError("receipt must be an EffectReceipt")
        receipt_id = receipt.receipt_id
        current_id = self._by_tool_call.get(receipt.tool_call_id)
        if current_id is not None:
            if current_id != receipt_id:
                raise ValueError("tool call ID already belongs to another receipt")
            return receipt_id
        if receipt_id in self._receipts:
            return receipt_id
        if self._path is not None:
            self._path.parent.mkdir(parents=True, exist_ok=True)
            existed = self._path.exists()
            line = (
                json.dumps(
                    receipt.to_dict(),
                    allow_nan=False,
                    ensure_ascii=True,
                    sort_keys=True,
                    separators=(",", ":"),
                )
                + "\n"
            ).encode("utf-8")
            descriptor = self._open_file(os.O_WRONLY | os.O_APPEND | os.O_CREAT)
            try:
                fcntl.flock(descriptor, fcntl.LOCK_EX)
                view = memoryview(line)
                while view:
                    written = os.write(descriptor, view)
                    view = view[written:]
                os.fsync(descriptor)
            finally:
                os.close(descriptor)
            if not existed:
                parent = os.open(
                    self._path.parent,
                    os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
                )
                try:
                    os.fsync(parent)
                finally:
                    os.close(parent)
        self._index(receipt)
        return receipt_id

    def get(self, receipt_id: str) -> EffectReceipt | None:
        """Return a verified receipt, or None when the ID is absent."""

        receipt = self._receipts.get(receipt_id)
        if receipt is not None and receipt.receipt_id != receipt_id:
            raise ValueError("stored receipt digest does not match its payload")
        return receipt

    def require(self, receipt_id: str) -> EffectReceipt:
        """Return a verified receipt or raise KeyError when it is absent."""

        receipt = self.get(receipt_id)
        if receipt is None:
            raise KeyError(f"receipt not found: {receipt_id}")
        return receipt

    def by_tool_call(self, tool_call_id: str) -> EffectReceipt | None:
        """Return the receipt for one tool-call ID, when recorded."""

        receipt_id = self._by_tool_call.get(tool_call_id)
        return self.get(receipt_id) if receipt_id is not None else None

    def __iter__(self):
        for receipt_id in self._order:
            yield self.require(receipt_id)

    def __len__(self) -> int:
        return len(self._order)

    def close(self) -> None:
        """Clear the in-memory index; durable receipt bytes remain on disk."""

        self._receipts.clear()
        self._by_tool_call.clear()
        self._order.clear()
